l=lock?'🔒&nbsp;':'';
type=$.chaptertype=='1';
num=!type?$.chapterid+'丨':'';
result=l+num+title+sms;
result=String(result).replace(/^🔒&nbsp;undefined丨undefined\d+\:/,'')

ruleToc.chapterUrl:
@js:
$=result;
novelid=$.novelid;
chapterid=$.chapterid;
vip=$.isvip=='1';
type=$.chaptertype=='1';
if(!type){
	if(!vip){
result='https://app.jjwxc.org/androidapi/chapterContent?novelId='+novelid+'&chapterId='+chapterid
}else{result='https://app.jjwxc.org/androidapi/chapterContent?novelId='+novelid+'&versionCode=191&token='+cookie.getKey('https://m.jjwxc.net','sid')+'&chapterId='+chapterid}
}else{result=''}

